INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66354, 'spa', 'copulativo/enlace', 'Función copulativa que enlaza sujeto y predicado, ''es'', ''son'', identificando o atribuyendo cualidades.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66359, 'spa', 'locativo', 'Indicación de ubicación o posición, ''estar en'', ''encontrarse'', señalando dónde algo está situado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66363, 'spa', 'existencial', 'Afirmación de existencia o realidad, ''existe'', ''hay'', declarando la presencia o ser de algo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66388, 'spa', 'identificación/ecuativo', 'Equiparación o identificación plena de sujeto y predicado, ''X es Y'', estableciendo identidad completa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66422, 'spa', 'Ser o existir', 'Hechos 8:37, aunque de autenticidad textual incierta en muchos manuscritos, contiene el infinitivo εἶναι en la declaración de Felipe sobre la fe. Cada idioma emplea su infinitivo básico de «ser» (español «ser», francés «être»), ya que este es el verbo existencial-copulativo fundamental. El griego clásico y bíblico utiliza este infinitivo extensamente en construcciones de discurso indirecto, propósito, resultado y explicación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66423, 'spa', 'Si en verdad, puesto que', 'Condicional enfático que significa ''si en verdad'', ''puesto que'' o ''aun si'', reforzando la partícula condicional básica εἰ con πέρ para indicar que la suposición es seria, confiada o concesiva. En Ro 8:9 y 8:17 introduce condiciones tratadas como hechos establecidos (''puesto que ciertamente el Espíritu de Dios mora en vosotros''), mientras que en 1 Co 8:5 concede una hipótesis retórica (''aun si hay los llamados dioses'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66426, 'spa', 'Vivir en paz', 'Vivir en estado de paz y concordia con otros; mantener o buscar relaciones armoniosas. En Marcos 9:50 Jesús vincula este imperativo con la metáfora de la sal, sugiriendo que la disposición pacífica preserva la comunidad. Romanos 12:18 añade un realismo sobrio (''si es posible''), mientras 2 Corintios 13:11 y 1 Tesalonicenses 5:13 lo formulan como directriz comunitaria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66427, 'spa', 'paz, bienestar, armonia', 'Estado de plenitud, tranquilidad, armonia y relacion recta que abarca la concordia interpersonal, el descanso espiritual interior y la paz escatologica del reino de Dios. Como traduccion estandar de la Septuaginta para el hebreo shalom, eirene porta un peso pactual que trasciende la mera ausencia de guerra. Pasajes clave incluyen el don de paz de Jesus (Jn 14:27), el saludo del Resucitado (Jn 20:19) y la paz con Dios por la fe (Ro 5:1).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66432, 'spa', 'Que produce paz', 'Caracterizando lo que produce o encarna paz, este sentido aparece en descripciones de justicia y sabiduría. Hebreos 12:11 habla del fruto apacible eventual de la disciplina, mientras que Santiago 3:17 hace lo pacífico una característica distintiva de la sabiduría divina. El alemán ''friedlich'' y el francés ''paisible'' capturan la cualidad de ser pacífico en carácter y efecto, no meramente experimentando paz sino promoviendo activamente la paz.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66433, 'spa', 'Hacer la paz', 'Colosenses 1:20 declara que Cristo, «habiendo hecho la paz (εἰρηνοποιήσας) mediante la sangre de su cruz», logró la reconciliación cósmica. El español «habiendo hecho paz» y el alemán «Frieden machen» capturan esta acción pacificadora activa. El participio aoristo indica acción completada: la paz consumada a través de la cruz. No se trata de poseer paz pasivamente, sino de establecerla activamente mediante el sacrificio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66434, 'spa', 'Pacificadores activos', 'La bienaventuranza de Mateo 5:9 bendice a «los pacificadores (εἰρηνοποιοί)» con la promesa de ser llamados hijos de Dios. El español «pacificadores» y el francés «pacificateur» significan «quienes pacifican o hacen la paz», enfatizando el trabajo activo de reconciliación. No se trata de temperamentos pacíficos, sino de intervención activa para crear paz donde hay conflicto. El uso clásico incluye acepciones técnicas en contextos políticos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66435, 'spa', 'hacia/movimiento', 'Movimiento hacia el interior de un espacio o lugar, ''a'', ''hacia dentro de'', indicando dirección y entrada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66436, 'spa', 'para/propósito', 'Propósito, finalidad o meta de una acción, ''para'', ''con el fin de'', expresando intención.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66439, 'spa', 'hacia/direccional', 'Dirección general hacia un destino sin énfasis en entrada, ''hacia'', ''rumbo a'', marcando orientación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66449, 'spa', 'hasta/referencia', 'Referencia, relación o destinatario de algo, ''hasta'', ''para'', ''en relación con''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66455, 'spa', 'resultando en', 'Resultado o consecuencia de una acción, ''resultando en'', ''de modo que'', expresando desenlace o efecto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66471, 'spa', 'numeral cardinal uno', 'El numeral cardinal ''uno'', que marca una sola entidad, cantidad o instancia. Con 339 apariciones es abrumadoramente el uso dominante. Todas las lenguas principales lo traducen directamente — español ''un/una/uno'', francés ''un'', alemán ''ein'' — confirmando un núcleo interlingüístico estable. Jesús lo usa enfáticamente: ''ni una jota'' (Mt 5:18), ''uno de estos mandamientos más pequeños'' (Mt 5:19).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66473, 'spa', 'ordinal primero', 'Uso ordinal con el significado de ''primero'', especialmente en la expresión temporal fija μιᾷ τῶν σαββάτων, ''el primer día de la semana''. Los cuatro Evangelios emplean esta construcción en sus relatos de la resurrección (Mt 28:1; Mr 16:2; Lc 24:1; Jn 20:1). Las traducciones al español pasan de ''uno'' a ''primer/primero'', señalando que los traductores reconocen un valor ordinal y no cardinal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66476, 'spa', 'distributivo cada uno', 'Sentido distributivo que significa ''cada uno'' o ''uno por uno'', expresando atención individual dentro de un grupo. En Lc 4:40 Jesús impone las manos sobre cada enfermo εἷς ἕκαστος, y en Hch 21:19 Pablo relata lo que Dios hizo ''una por una'' entre las naciones. El español recurre a ''a uno'' o ''por una'', mostrando que se extiende más allá del sentido numérico básico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66478, 'spa', 'correlativo el otro', 'Uso correlativo con el significado de ''el otro'' en construcciones pareadas. En 1 Tesalonicenses 5:11, εἷς τὸν ἕνα establece una relación recíproca: ''unos a otros''. El español lo traduce como ''otro'' en vez de ''uno'', revelando que el sentido numérico ha cedido por completo a una función pronominal y relacional, desarrollo también atestiguado en el griego clásico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66486, 'spa', 'Introducir, hacer entrar', 'Introducir, hacer entrar. Conducir o llevar a alguien o algo a un lugar —una casa, templo, ciudad o la tierra prometida— como acción transitiva activa e intencional. Este sentido principal (9 ocurrencias) abarca contextos desde lo sagrado hasta lo doméstico: José y María llevando al niño Jesús a los atrios del templo (Lc 2:27), siervos trayendo a los desamparados de las calles para un banquete (Lc 14:21), y el sumo sacerdote introduciendo elementos en el culto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66487, 'spa', 'Ser introducido', 'Ser introducido. Ser llevado o conducido a un lugar por autoridad ajena, expresado en voz pasiva. Solo 2 ocurrencias, ambas en Hechos describiendo la custodia de Pablo: pide hablar cuando está ''a punto de ser llevado al cuartel'' (Hch 21:37), y el comandante ordena que sea ''llevado al cuartel'' para interrogarlo (Hch 22:24).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66495, 'spa', 'Or y responder favorablemente', 'Escuchar con disposicin favorable y responder, especialmente referido a Dios que oye y contesta la oracin. El francs ''exaucer'' (conceder, cumplir una splica) y el alemn ''erhoeren'' distinguen esto de la mera percepcin auditiva, enfatizando la respuesta divina. Las oraciones de Zacaras y Cornelio son declaradas ''odas'' con la implicacin de cumplimiento inminente (Lucas 1:13; Hechos 10:31). En Hebreos 5:7, Cristo fue escuchado por su piadosa reverencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66496, 'spa', 'Recibir en comunión', 'En 2 Corintios 6:17, Dios promete «yo os recibiré (εἰσδέξομαι)» a quienes se separen de la impureza. El español ''os recibiré'' y el francés ''accueillir'' subrayan la bienvenida relacional. El uso clásico incluía la admisión en templos o colonias. Aquí es la promesa pactal de Dios de recibir a su pueblo en intimidad con él.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66497, 'spa', 'Entrar, ingresar', 'Ir hacia dentro de un lugar, especialmente un edificio, espacio sagrado o asamblea. Alternativa más literaria de εἰσέρχομαι, predominante en Hechos y Hebreos. En Hechos 3:3 se entra al templo; Hechos 21:18 y 21:26 describen a Pablo visitando a Jacobo y purificándose en el templo; Hebreos 9:6 refiere la entrada regular de los sacerdotes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66498, 'spa', 'entrar en un lugar', 'Entrar físicamente en un lugar — ir a una casa, ciudad, templo, barca u otra ubicación delimitada. Es el sentido por defecto y más frecuente (179 de 195 apariciones). Pasajes clave incluyen a Jesús entrando en la sinagoga (Mr 1:21), entrando en Jerusalén (Mt 21:10) y entrando en el templo (Mt 21:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66502, 'spa', 'entrar en un estado', 'Entrar figuradamente en un estado, condición o realidad espiritual — como entrar en el reino de Dios, entrar en la vida, entrar en el reposo o entrar en el gozo. Presente en declaraciones teológicas cruciales como ''si no os volvéis y os hacéis como niños, no entraréis en el reino de los cielos'' (Mt 18:3) y ''entra en el gozo de tu señor'' (Mt 25:21).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66520, 'spa', 'pasar a través de', 'Pasar o atravesar un paso estrecho o difícil, como en el dicho del camello y el ojo de la aguja (Mt 19:24). El español ''pasar'' aparece junto al estándar ''entrar'', sugiriendo que los traductores perciben la imagen más como travesía que como simple entrada. El sentido está emparentado con la entrada física pero enfatiza la dificultad o imposibilidad del paso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66537, 'spa', 'Ser en plural', 'En 1 Juan 5:7, pasaje textualmente disputado y ausente en manuscritos antiguos, εἰσί aparece en declaraciones sobre testigos. Cada idioma usa su tercera persona del plural de ''ser'' (español ''son'', alemán ''sie sind''), pues es simplemente la cópula plural. La forma aparece miles de veces en la literatura griega para cualquier predicación o existencia en plural.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66538, 'spa', 'Invitar a entrar', 'En Hechos 10:23, Pedro «los invitó a entrar (εἰσκαλεσάμενος)» cuando los mensajeros gentiles de Cornelio llegaron, un acto significativo dadas las costumbres de separación entre judíos y gentiles. El español ''invitando adentro'' capta la acogida espacial, mientras que la voz media muestra la iniciativa personal de Pedro. El uso clásico incluía invitar a la propia casa o convocar para consulta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66539, 'spa', 'Entrada o acceso', 'Una entrada, ingreso o llegada; abarca tanto el acto fsico de entrar en un lugar como la recepcin o bienvenida al llegar, as como el derecho de acceso. Pablo recuerda su ''entrada'' inicial entre los tesalonicenses, la calidad de su llegada y la acogida recibida (1 Tesalonicenses 1:9; 2:1). Hebreos 10:19 lo usa para el acceso confiado a la presencia de Dios mediante el sacrificio de Cristo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66540, 'spa', 'Irrumpir con urgencia', 'En Marcos 10:50 el ciego Bartimeo responde al llamado de Jesús arrojando su manto, saltando y acudiendo a él con prontitud. En Hechos 14:14 Pablo y Bernabé se rasgan las vestiduras y se lanzan entre la multitud al ver que intentan ofrecerles sacrificios. En Hechos 16:29 el carcelero de Filipos irrumpe temblando tras el terremoto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66541, 'spa', 'Entrar, pasar adentro', 'Entrar, pasar adentro: moverse fisicamente hacia un espacio cerrado o delimitado — una casa, sinagoga, ciudad o aldea — o figuradamente hacia la vida interior de una persona. Marcos es el usuario principal, representando a Jesus entrando en la sinagoga de Capernaum (Mr 1:21), una casa con dolientes (Mr 5:40), y aldeas donde las multitudes se agolpan para tocarlo (Mr 6:56). La extension figurada en Marcos 4:19 presenta las preocupaciones mundanas ''entrando'' para ahogar la palabra sembrada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66551, 'spa', 'Entrar corriendo', 'En Hechos 12:14, Rode «habiendo corrido adentro (εἰσδραμοῦσα)» con gozo tras reconocer la voz de Pedro, en su emoción olvidó abrir la puerta. El español ''corriendo adentro'' y el francés ''entrer en courant'' preservan el movimiento apresurado hacia el interior. El participio aoristo sugiere una acción rápida y decidida: ella se lanzó adentro para anunciar la presencia de Pedro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66552, 'spa', 'Conducir a tentación', 'Conducir o llevar a una situación, especialmente de tentación o prueba, como extensión figurada del sentido espacial. El Padrenuestro pide a Dios que «no nos metas» (εἰσενέγκῃς) en tentación (Mt 6:13; Lc 11:4), un uso que ha generado siglos de reflexión teológica sobre la prueba divina. En Lucas 12:11 se advierte a los creyentes sobre ser «llevados ante» sinagogas y autoridades.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66553, 'spa', 'Meter, introducir físicamente', 'Llevar o introducir físicamente a una persona o cosa dentro de un lugar, cruzando un umbral hacia un espacio interior. Los amigos intentan meter al paralítico en la casa (Lc 5:18-19). Pablo reflexiona que nada se trae al mundo al nacer ni se saca al morir (1 Ti 6:7). En Hechos 17:20 los atenienses dicen que Pablo «trae cosas extrañas a nuestros oídos», y Hebreos 13:11 habla de la sangre que es introducida en el santuario.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66559, 'spa', 'Luego, después, a continuación — un adverbio de secuenciación temporal y lógica ', 'Luego, después, a continuación — un adverbio de secuenciación temporal y lógica que indica lo que viene después en una serie. Marcos 4:28 ilustra vívidamente el uso temporal: la tierra produce ''primero la hierba, luego la espiga, después el grano lleno''. Pablo lo usa para ordenar las apariciones de la resurrección (1 Co 15:5, 7) y los eventos escatológicos (1 Co 15:24). También sirve para avanzar la argumentación lógica (1 Ti 2:13; He 12:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66560, 'spa', 'sea...o, ya sea...ya sea', 'Conjuncion disyuntiva empleada en pares (eite...eite) para presentar alternativas como igualmente posibles o equivalentes, formando construcciones equilibradas de ''sea...o''. Pablo la despliega de modo prominente: ''sea judios o griegos, sea esclavos o libres'' (1 Co 12:13), y el extenso catalogo de 1 Co 3:22 (''sea Pablo, sea Apolos, sea Cefas''). Tambien introduce pares en la lista de dones espirituales de Romanos 12:6-8.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66561, 'spa', 'fuera de/desde dentro', 'Movimiento desde el interior hacia el exterior; salir de un lugar o espacio cerrado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66562, 'spa', 'de/procedencia u origen', 'Indica la fuente, el lugar de origen, o la procedencia de donde algo o alguien proviene.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66564, 'spa', 'a causa de/causal', 'Expresa la razón, motivo o causa de una acción o estado; por motivo de, debido a.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66568, 'spa', 'cada uno, cada cual', 'Adjetivo o pronombre distributivo que significa ''cada uno'' o ''cada individuo'', aislando a los miembros de un grupo para atencion individual en vez de tratarlos colectivamente. Teologicamente importante en contextos de responsabilidad personal: ''cada uno recibira su propia recompensa'' (1 Co 3:8), ''si cada uno de vosotros no perdona'' (Mt 18:35). Tambien se usa en distribuciones narrativas como Lc 2:3 (''cada uno iba a inscribirse'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66577, 'spa', 'Cada vez', 'En 2 Pedro 1:15, Pedro se compromete a asegurar que los creyentes recuerden su enseñanza «cada vez (ἑκάστοτε)» tras su partida, sugiriendo provisión escrita para referencia continua. El español ''cada vez'' y el alemán ''jedesmal'' captan el sentido temporal distributivo. El uso clásico confirma el significado de ''en cada ocasión'', enfatizando la repetición en distintas instancias.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66578, 'spa', 'Cien', 'Cien: el numero cardinal cien, usado como cantidad exacta. En la parabola del sembrador describe el rendimiento maximo de la buena tierra — un retorno del ciento por uno (Mt 13:8, 23). En las parabolas de la oveja perdida (Mt 18:12; Lc 15:4) y del siervo que no perdona (Mt 18:28), establece la escala de lo que esta en juego. La palabra es indeclinable y funciona de manera identica en todo contexto gramatical.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66580, 'spa', 'Centenario de edad', 'Romanos 4:19 describe a Abraham como ''de unos cien años (ἑκατονταέτης)'' al enfrentar la incapacidad natural de su cuerpo envejecido para engendrar descendencia, resaltando el milagro del nacimiento de Isaac. En el uso clásico, el término se aplicaba tanto a personas como a períodos de tiempo centenarios. El contexto paulino subraya la imposibilidad humana superada por la promesa divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66581, 'spa', 'Retorno centuplicado', 'Los paralelos sinópticos registran la promesa de Jesús a quienes lo dejan todo por su causa. Mateo 19:29 promete que recibirán cien veces más. Marcos 10:30 añade un matiz temporal: recibirán el céntuplo «ahora en este tiempo, con persecuciones, y en el siglo venidero, la vida eterna». Lucas 8:8 lo emplea en la parábola del sembrador para describir la semilla que dio fruto al céntuplo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66582, 'spa', 'Oficial militar romano a cargo de una centuria (nominalmente 100 soldados), coma', 'Oficial militar romano a cargo de una centuria (nominalmente 100 soldados), comandante clave de rango medio en el ejército romano. En el Nuevo Testamento, los centuriones aparecen consistentemente bajo una luz positiva: el centurión de Capernaum cuya fe asombró a Jesús (Mt 8:5-13; Lc 7:2-10), el oficial en la crucifixión que reconoció la identidad de Jesús (Mt 27:54; Mr 15:39) y Cornelio, el centurión temeroso de Dios que fue el primer converso gentil (Hch 10). Son figuras de autoridad que, paradójicamente, reconocen una autoridad superior.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66586, 'spa', 'echar fuera / expulsar', 'Sentido dominante de expulsión enérgica: echar fuera demonios, expulsar personas o retirar entidades de un lugar o comunidad. Con cincuenta y tres apariciones, constituye el núcleo abrumador de ἐκβάλλω en el Nuevo Testamento, abarcando los exorcismos de Jesús (Mt 8:16; Mr 1:34; Lc 11:14), la comisión de los discípulos para echar fuera demonios (Mt 10:1; Mr 3:15; 6:13) y la remoción de personas de asambleas o lugares.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66591, 'spa', 'producir / sacar a luz', 'Sentido metafórico-productivo de sacar a luz o producir de una fuente: cinco apariciones donde ἐκβάλλω describe extraer bienes de un tesoro o depósito. El escriba instruido en el reino ''saca'' cosas nuevas y viejas (Mt 13:52); la persona buena ''saca'' lo bueno del buen tesoro de su corazón (Mt 12:35). Juan 10:4 lo extiende al pastor que ''saca'' a sus ovejas con ternura.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66594, 'spa', 'enviar / despachar', 'Sentido de comisión y envío: despachar o enviar a alguien con un propósito, donde la connotación de fuerza se minimiza y el énfasis recae en la misión deliberada. Jesús insta a orar para que el Señor de la mies ''envíe'' obreros (Mt 9:38; Lc 10:2), y Santiago 2:25 describe a Rahab ''enviando'' a los espías por otro camino. Marcos 1:43 lo usa para Jesús ''despidiendo'' al leproso sanado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66597, 'spa', 'sacar / extraer', 'Sentido extractivo más delicado: sacar o quitar un objeto físico de un sitio, especialmente en el discurso de la paja y la viga del Sermón del Monte (Mt 7:4-5; Lc 6:42) y el mandato hiperbólico de arrancarse un ojo que ofende (Mr 9:47). Siete apariciones portan este sentido, donde la acción requiere cuidado o precisión más que fuerza bruta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66599, 'spa', 'arrojar / rechazar con violencia', 'Lanzamiento o arrojo violento: echar a alguien o algo con fuerza física, como los labradores que arrojaron al heredero fuera de la viña y lo mataron (Mt 21:39; Mr 12:8; Lc 20:15), o el siervo echado a las tinieblas de afuera (Mt 22:13; 25:30). Seis apariciones subrayan la brutalidad física de la acción, incluyendo a los marineros que arrojan la carga al mar (Hch 27:38).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66606, 'spa', 'ser echado fuera (pasivo)', 'Voz pasiva: ser expulsado, echado fuera o arrojado por otro agente, con seis apariciones donde el sujeto sufre la acción. Los hijos del reino ''serán echados'' a las tinieblas de afuera (Mt 8:12), y quienes comieron y bebieron en presencia de Jesús se hallan expulsados afuera (Lc 13:28). La morfología pasiva en español se expresa con fue echado fuera, será echado, siendo echados.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66635, 'spa', 'Salida o desenlace', 'En 1 Corintios 10:13, Dios promete proveer una salida frente a la tentación: la puerta de escape del peligro moral. En Hebreos 13:7, se exhorta a considerar el desenlace de la conducta de los líderes fieles. El término abarca tanto la liberación divina como el resultado final de una vida de fe.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66636, 'spa', 'Echazón náutica', 'Hechos 27:18 describe cómo la tripulación realizó ''una echazón (ἐκβολήν)'' durante la violenta tormenta que amenazó el viaje de Pablo a Roma. El término técnico náutico designa la eliminación de emergencia de la carga para salvar la nave. En el uso clásico también podía significar expulsión en otros contextos, pero aquí se refiere al aligeramiento del barco en peligro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66637, 'spa', 'Nietos o descendientes', 'Primera Timoteo 5:4 aborda la responsabilidad hacia las viudas: si ella tiene ''nietos (ἔκγονα)'', estos deben practicar la piedad cuidándola. El uso clásico muestra que podía significar cualquier descendiente o específicamente nietos (ἐκγόνων ἔκγονοι = hijos de los hijos). El contexto paulino enfatiza la obligación filial de sostener a los mayores de la familia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66638, 'spa', 'Ser gastado completamente', 'Segunda Corintios 12:15 contiene la apasionada promesa de Pablo: ''Con gusto gastaré y seré gastado (ἐκδαπανηθήσομαι)'' por las almas de los corintios. El futuro pasivo expresa la disposición de Pablo a ser consumido por completo en el ministerio. El uso clásico incluía el agotamiento de provisiones. El contexto paulino le confiere un matiz de entrega sacrificial y abnegación pastoral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66639, 'spa', 'Esperar, aguardar', 'Esperar a alguien o algo con expectativa activa y paciencia, anticipando un resultado definido. La palabra transmite una nota de perseverancia con proposito mas que de demora pasiva. En Betesda los enfermos aguardan el movimiento del agua (Jn 5:3); Pablo espera expectante en Atenas (Hch 17:16); a los creyentes se les dice que se esperen unos a otros en la mesa del Senor (1 Co 11:33). La cumbre teologica llega en Hebreos 10:13, donde Cristo mismo aguarda la sujecion de sus enemigos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66646, 'spa', 'Plenamente evidente', 'Segunda Timoteo 3:9 promete que la insensatez de los falsos maestros ''será evidente (ἔκδηλος) para todos'', quedando su error al descubierto. La forma intensificada (prefijo ἐκ- reforzando δῆλος = claro) significa ''totalmente patente'' o ''conspicuo para todos''. Pablo asegura a Timoteo que el engaño termina por autoexponerse: lo que pretendía permanecer oculto se vuelve indiscutiblemente manifiesto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66647, 'spa', 'Ausencia peregrina', 'Las tres apariciones se concentran en 2 Corintios 5:6-9, la meditación de Pablo sobre la mortalidad y la esperanza. Estar ''en casa en el cuerpo'' equivale a estar ''fuera de casa respecto al Señor''. Pablo expresa su preferencia por partir del cuerpo y estar en la presencia del Señor, convirtiendo la vida terrenal en un peregrinaje transitorio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66648, 'spa', 'Arrendar propiedad', 'Dar en arriendo una propiedad a arrendatarios, especialmente tierra agrícola. En el NT aparece exclusivamente en la Parábola de los Labradores Malvados, donde el dueño arrienda su viña antes de partir (Mt 21:33; Mc 12:1; Lc 20:9) y donde el juicio implica re-arrendarla a labradores dignos (Mt 21:41).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66649, 'spa', 'narración detallada', 'Refiriéndose a la narración detallada y exhaustiva de eventos, este sentido enfatiza el reporte completo en lugar del resumen. Hechos 13:41 lo usa en un contexto profético para declarar la obra sorprendente de Dios, mientras que 15:3 describe el relato detallado de los misioneros sobre las conversiones de los gentiles que trae gozo a los creyentes. Las traducciones españolas ''relatando'' y francesas ''exposer'' sugieren exposición y descripción completa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66650, 'spa', 'Vengar, ejecutar venganza', 'Vengar, ejecutar justicia retributiva en nombre de alguien agraviado, con enfasis en la accion punitiva contra el agresor. En Romanos 12:19 Pablo cita Deuteronomio: ''Mia es la venganza'', y en Apocalipsis 6:10 los martires bajo el altar claman para que Dios vengue su sangre. Segunda Corintios 10:6 habla de estar prontos para castigar toda desobediencia. El campo semantico abarca castigar, tomar represalias y ejecutar juicio divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66651, 'spa', 'Vindicar, hacer justicia', 'Vindicar, otorgar o asegurar justicia para alguien que ha sido agraviado, enfocandose en el alivio de la victima mas que en el castigo del ofensor. En la parabola de la viuda persistente (Lc 18:3, 5), la mujer suplica ''hazme justicia contra mi adversario'', y el juez finalmente resuelve concederle sus derechos. Este sentido restaurativo muestra la amplitud del termino griego, que va mas alla de la mera retribucion.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66656, 'spa', 'Venganza, retribución divina', 'Retribución divina o venganza ejecutada por Dios contra los malhechores. Pablo cita Deuteronomio: «Mía es la venganza, yo pagaré» (Ro 12:19); Lucas 21:22 habla de «días de venganza» como ajuste de cuentas escatológico. En 2 Tesalonicenses 1:8 este uso se vincula al juicio final, subrayando la orientación punitiva dirigida desde Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66657, 'spa', 'Vindicación, justicia', 'Vindicación o consecución de justicia para la parte oprimida, con el foco en la víctima más que en el ofensor. En la parábola de la viuda insistente (Lc 18:7-8), Dios promete «hacer justicia» a sus elegidos. El español pasa notablemente de «venganza» a «justicia» aquí, revelando una distinción semántica que el griego original deja al contexto: el clamor es por liberación, no por destrucción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66658, 'spa', 'Castigo judicial', 'Castigo judicial administrado por las autoridades civiles como instrumentos del orden divino. En 1 Pedro 2:14, los gobernantes son enviados «para castigo de los malhechores» (εἰς ἐκδίκησιν κακοποιῶν). El término «castigo» marca esta acepción como institucional y correctiva, distinta tanto de la venganza personal como de la vindicación centrada en la víctima.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66662, 'spa', 'ejecutor de venganza', 'Describiendo a quien ejecuta venganza o impone justicia, este sentido se aplica tanto a las autoridades civiles (Rom 13:4) como a Dios mismo (1 Tes 4:6). La traducción consistente como ''vengador'' refleja el rol activo de ejecutar ira contra la maldad. Romanos conecta esto con la autoridad gubernamental legítima, mientras que 1 Tesalonicenses advierte sobre la retribución divina por el pecado sexual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66663, 'spa', 'Perseguir y expulsar', '1 Tesalonicenses 2:15 describe a quienes «habiendo expulsado (ἐκδιωξάντων)» a Pablo y sus compañeros, en el contexto de haber matado a Jesús y a los profetas. El español «que persiguieron» y el alemán «verfolgen» enfatizan la persecución hostil más que la simple expulsión. El participio aoristo indica acción completada. El uso clásico abarcaba desde el destierro hasta la persecución violenta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66664, 'spa', 'Entregado al poder ajeno', 'Hechos 2:23 describe a Jesús como «entregado (ἔκδοτον)» según el plan predeterminado de Dios para ser crucificado. El español «entregado» y el francés «livrer» transmiten la transferencia al poder de otros. El uso clásico incluía ser traicionado, entregado a enemigos o dado en matrimonio, siempre implicando transferencia a la autoridad de otro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66665, 'spa', 'Expectación temerosa', 'Hebreos 10:27 advierte sobre «una horrenda expectación (ἐκδοχή) de juicio y ardor de fuego» que aguarda a los apóstatas. El español «expectación» y el alemán «Erwartung» significan expectativa, mientras que el francés «attente» enfatiza la dimensión temporal. El uso clásico incluía tanto expectativa como opinión (relacionado con δοκέω). Aquí no es anticipación esperanzadora sino certeza terrible.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66666, 'spa', 'Despojar de vestiduras', 'Quitar o arrancar la ropa a alguien, ya sea por la fuerza o voluntariamente. Las cinco apariciones en el NT se agrupan en torno al acto fsico o metafrico de desvestir. Los relatos sinpticos de la Pasin lo usan para describir a los soldados despojando a Jess (Mateo 27:28, 31; Marcos 15:20), mientras que Lucas 10:30 describe a los salteadores desnudando a un viajero. Pablo extiende la imagen en 2 Corintios 5:4, donde el temor de quedar ''desvestido'' alude a la muerte antes de la resurreccin.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66667, 'spa', 'allí', 'Adverbio locativo que significa ''allí, en aquel lugar'', señalando una ubicación distinta de la posición del hablante. A lo largo de sus 95 apariciones neotestamentarias, sirve a la geografía narrativa situando eventos en sitios específicos (Mt 2:13, 15; Jn 11:15) y a veces absorbe fuerza direccional (''hacia allá'', con verbos de movimiento). Sus usos teológicamente más resonantes incluyen Mt 18:20 (''allí estoy yo en medio de ellos'') y Jn 11:15.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66669, 'spa', 'Adverbio espacial que significa ''de allí'' o ''desde aquel lugar,'' funcionando com', 'Adverbio espacial que significa ''de allí'' o ''desde aquel lugar,'' funcionando como marcador de transición en las narrativas itinerantes de los Evangelios. Aparece de manera característica en la fórmula ''y partiendo de allí'' que traslada a Jesús entre distintos lugares de ministerio (Mt 9:9, 27; 11:1; 12:9, 15; 13:53; 15:21, 29; Mr 6:1, 10; 9:30; 10:1). También transmite un sentido de finalidad: no se saldrá ''de allí'' hasta haber pagado el último centavo (Mt 5:26). En Hechos 7:4 se refiere a la migración de Abraham desde Harán.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66671, 'spa', 'aquel, aquellos (demostrativo)', 'Demostrativo atributivo o adjetival: ''aquel'' o ''aquellos'' modificando un sustantivo, señalando a un referente mencionado previamente o contextualmente distante — 170 apariciones. ''En aquel día'' (Mt 7:22), ''en aquella hora'' (Mt 8:13), ''aquellas ciudades'' (Mt 11:24). El uso temporal es especialmente prominente en el discurso escatológico, donde ''aquel día'' se convierte en término casi técnico para el día del juicio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66672, 'spa', 'aquel, él/ella (sustantivo)', 'Pronombre sustantivo que refiere a un individuo específico: ''aquel'', ''él'', ''ella'' — 63 apariciones, especialmente concentradas en el Evangelio de Juan. Cuando Juan el Bautista señala a Jesús como ''aquel que viene después de mí'' (Jn 1:15, 27, 30), ἐκεῖνος porta una fuerza enfática, casi reverencial. En Jn 14-16 el Espíritu es llamado repetidamente ἐκεῖνος (''aquel os enseñará'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66676, 'spa', 'aquellos (sustantivo, personas)', 'Sustantivo plural: ''aquellos'' o ''ellos'' con énfasis demostrativo — 12 apariciones donde un grupo previamente identificado o contrastado es distinguido. En Mt 13:11 se dice a los discípulos ''a vosotros os es dado... pero a aquellos no''; en Mr 16:13 la aparición del Jesús resucitado se anuncia ''a aquellos'' discípulos restantes. El plural demostrativo funciona como un distanciamiento moderado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66695, 'spa', 'dirección espacial', 'Indicando dirección espacial ''a aquel lugar'', este adverbio marca movimiento hacia un destino previamente mencionado. Hechos 21:3 describe navegar allí (a Tiro), mientras que 22:5 describe el viaje de Pablo allí (a Damasco). Las traducciones simples en varios idiomas (''there'', ''allí'', ''là'') reflejan su función deíctica básica señalando una ubicación en el contexto narrativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66696, 'spa', 'Buscar con diligencia', 'Buscar con fervor, indagar con diligencia y minuciosidad, especialmente en el contexto religioso de buscar a Dios o la verdad divina. El prefijo ἐκ- intensifica el basico ζητέω, transmitiendo no una indagacion casual sino una busqueda decidida. Cinco de las siete apariciones en el NT corresponden a este sentido: los gentiles que ''buscaran al Senor'' en la era mesianica (Hch 15:17), la cita de Pablo de que ''nadie busca a Dios'' (Ro 3:11) y la recompensa prometida a quienes le buscan (He 11:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66699, 'spa', 'Demandar, requerir cuentas', 'Demandar rendicion de cuentas, requerir de vuelta: un sentido juridico en el que algo (especialmente la culpa de sangre) es exigido al responsable. Distinto del sentido de ''buscar'', aparece en Lucas 11:50-51, donde Jesus declara que ''la sangre de todos los profetas derramada desde la fundacion del mundo sera demandada a esta generacion''. La construccion pasiva subraya la solemnidad de la rendicion de cuentas divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66703, 'spa', 'Asombro intenso', 'Ser sobrecogido por un asombro intenso que puede derivar en alarma o angustia, superando la sorpresa ordinaria. Exclusivo de Marcos, capta reacciones emocionales abrumadoras: el asombro de la multitud (Mc 9:15), la angustia de Jesús en Getsemaní (Mc 14:33) y el estupor aterrorizado de las mujeres ante el ángel en el sepulcro (Mc 16:5-6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66704, 'spa', 'Asombro abrumador', 'Hechos 3:11 describe a la multitud como «grandemente asombrada (ἔκθαμβοι)» tras presenciar al hombre anteriormente cojo caminando y aferrado a Pedro y Juan. El español «asombrados» y el francés «très étonné» transmiten un asombro intensificado. El prefijo intensivo (ἐκ-) refuerza el asombro ordinario (θαμβέω) hasta convertirlo en estupefacción abrumadora. El uso clásico mostraba tanto admiración positiva como temor reverencial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66705, 'spa', 'Abandono de infantes', 'Hechos 7:19 describe la estratagema del Faraón que obligaba a los hebreos «a exponer (ἔκθετα) a sus bebés» para que no sobrevivieran. El español «expuestos» y el francés «exposé» son el término técnico para el abandono infantil. El uso clásico confirma esta práctica de niños «enviados fuera de la casa» y dejados a morir, común en el mundo grecorromano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66706, 'spa', 'purificación exhaustiva', 'Refiriéndose a la purificación exhaustiva o remoción de contaminación, este sentido se aplica a la limpieza tanto moral como ceremonial. 1 Corintios 5:7 usa la imagen de la Pascua de remover la vieja levadura, mientras que 2 Timoteo 2:21 habla de autopurificación de vasijas deshonrosas. La metáfora enfatiza la remoción completa de lo que contamina, no meramente cubrirlo o controlarlo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66707, 'spa', 'Arder en pasión', 'Romanos 1:27 describe a varones que ''se encendieron (ἐξεκαύθησαν) en su deseo unos por otros,'' según la descripción paulina de la pasión desordenada. El español ''se encendieron'' y el alemán ''entbrennen'' emplean metáforas de fuego para el deseo intenso. El aoristo pasivo sugiere ser arrebatado por la pasión, incluyendo tanto fuego literal como arder figurado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66708, 'spa', 'Desmayar, desfallecer', 'Desalentarse, perder el animo o cansarse bajo una dificultad prolongada. La palabra retrata un marchitamiento interior de la resolucion mas que simple cansancio fisico. Jesus la introduce en Lucas 18:1 como contraste a la oracion persistente, y Pablo la adopta como estribillo recurrente: a pesar de la afliccion, el desgaste del cuerpo y la cosecha demorada, los creyentes no deben desmayar (2 Co 4:1, 4:16; Ga 6:9; Ef 3:13).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66712, 'spa', 'traspasar a Cristo', 'Describiendo el acto de traspasar a Cristo con una lanza, este sentido aparece en citas directas y alusivas de Zacarías 12:10. Juan 19:37 aplica la profecía al golpe de lanza del soldado, mientras que Apocalipsis 1:7 lo conecta con el regreso de Cristo cuando todas las tribus verán al que traspasaron. Las traducciones consistentes (''pierced'', ''traspasaron'', ''percer'', ''durchstechen'') enfatizan la violencia penetrante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66713, 'spa', 'Desgajamiento del olivo', 'Las tres apariciones se encuentran en la alegoría del olivo de Pablo (Romanos 11:17-20), describiendo la remoción de los israelitas infieles de la relación pactual. La construcción en voz pasiva (fueron desgajadas) enfatiza la acción divina. El término transmite una separación violenta y deliberada, no un simple desprendimiento natural.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66714, 'spa', 'Exclusión de participación', 'Refiriéndose a la exclusión o el cierre del acceso a la participación o beneficio, este sentido aparece en los argumentos teológicos de Pablo. Romanos 3:27 habla de que la jactancia es excluida por la ley de la fe, mientras Gálatas 4:17 advierte sobre maestros falsos que quieren cerrar el acceso a los creyentes de una relación apropiada. La metáfora de una puerta cerrada captura la prevención del acceso o participación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66715, 'spa', 'iglesia, comunidad cristiana', 'La iglesia cristiana como comunidad de creyentes (105 apariciones), abarcando tanto congregaciones locales como el cuerpo universal de Cristo. Pablo dirige sus cartas a iglesias de ciudades específicas (1 Co 1:2; 1 Ts 1:1) y a la vez habla de Cristo como cabeza de ''la iglesia'' como realidad cósmica (Ef 5:23-25). Hechos traza el crecimiento de la iglesia primitiva desde Jerusalén (Hch 5:11; 8:1) hasta comunidades por todo el Mediterráneo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66719, 'spa', 'asamblea, congregación (no técnico)', 'Asamblea o congregación reunida sin referencia específicamente cristiana (9 apariciones). El discurso de Esteban en Hch 7:38 lo usa para Israel reunido en el Sinaí — ''la congregación en el desierto'' — evocando la traducción de la LXX del hebreo קָהָל. El episodio de los plateros de Éfeso (Hch 19:32, 39, 41) lo emplea en su sentido cívico original de asamblea pública, tanto tumultuosa como legítima.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66725, 'spa', 'Desviación deliberada', 'Romanos 3:12 cita el Salmo 14: ''Todos se desviaron, a una se hicieron inútiles'', describiendo la desviación universal del camino de Dios. Romanos 16:17 exhorta a apartarse de los que causan divisiones. 1 Pedro 3:11 aconseja apartarse del mal y hacer el bien. El verbo abarca tanto el extravío pecaminoso como la separación protectora.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66726, 'spa', 'Escapar nadando', 'Hechos 27:42 describe a soldados que querían matar a los presos para impedir que alguno ''nadara hacia afuera (ἐκκολυμβήσας)'' y escapara durante el naufragio. El español ''habiendo nadado'' conserva la acción pero no el matiz direccional. El uso clásico especificaba nadar desde un barco hasta la orilla; el compuesto enfatiza alejarse nadando.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66727, 'spa', 'Llevar al entierro', 'Lucas 7:12 describe a un difunto que ''era llevado (ἐξεκομίζετο)'' fuera de Naín para su sepultura cuando Jesús encontró la procesión fúnebre. El español ''era llevado'' y el francés ''emporter'' transmiten la acción de transporte. El imperfecto pasivo sugiere una procesión en curso. El uso clásico incluía también sacar objetos a lugar seguro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66728, 'spa', 'Talar un árbol', 'Talar un árbol. Cortar un árbol entero, usado literal y metafóricamente como imagen de juicio divino sobre lo infructuoso. La imagen del hacha a la raíz de Juan el Bautista (Mt 3:10; Lc 3:9) y la parábola de Jesús sobre la higuera estéril (Lc 13:7, 9) emplean este sentido: el organismo entero es destruido, no simplemente podado. El tiempo presente subraya la inminencia del juicio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66729, 'spa', 'Cortar, amputar', 'Cortar, amputar. Cortar o amputar una parte de un todo mayor —una mano, un pie o una rama que se quita mientras el cuerpo o árbol sobrevive. Los dichos radicales de Jesús sobre el discipulado (Mt 5:30; 18:8) ordenan la autoamputación de lo que causa pecado, y la alegoría paulina del olivo en Romanos 11:22, 24 describe ramas incrédulas ''desgajadas'' para que las silvestres sean injertadas. En 2 Corintios 11:12, la metáfora se extiende a cortar la oportunidad de los falsos apóstoles.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66735, 'spa', 'Escuchar absorto', 'Lucas 19:48 describe cómo el pueblo ''estaba pendiente (ἐξεκρέματο) de él'' para oír a Jesús, tan cautivado que parecía suspendido de sus palabras. El español ''estaba pendiente'' y el francés ''être suspendu'' conservan la metáfora de colgar. El uso clásico incluía el sentido literal de colgar y el figurado de aferrarse con devoción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66736, 'spa', 'Divulgar o revelar', 'Hechos 23:22 registra al tribuno ordenando al sobrino de Pablo ''que a nadie dijera (μηδενὶ ἐκλαλῆσαι)'' sobre el complot de asesinato. El español ''digas'' y el francés ''déclarer'' son verbos neutrales. El uso clásico tenía sentidos más fuertes: ''soltar la lengua, delatar,'' con implicaciones de indiscreción. Aquí el infinitivo con negación ordena guardar silencio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66737, 'spa', 'Resplandecer gloriosamente', 'Mateo 13:43 contiene la gloriosa promesa de Jesús: «Entonces los justos resplandecerán (ἐκλάμψουσιν) como el sol en el reino de su Padre.» El tiempo futuro apunta a una transformación escatológica. El prefijo compuesto (ἐκ-) intensifica el brillo básico, enfatizando no solo poseer luz, sino irradiarla hacia afuera con esplendor visible y glorioso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66738, 'spa', 'Olvido completo', 'Hebreos 12:5 pregunta retóricamente si los lectores «han olvidado por completo (ἐκλέλησθε)» la exhortación paternal de Dios que se dirige a ellos como hijos. El tiempo perfecto sugiere un estado de olvido que persiste. El prefijo intensificador (ἐκ-) convierte el simple «olvidar» en «olvidar totalmente», indicando un desvanecimiento profundo y prolongado de la memoria espiritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66739, 'spa', 'Elegir, seleccionar o escoger a alguien o algo para un propósito o función parti', 'Elegir, seleccionar o escoger a alguien o algo para un propósito o función particular. Predominan las formas aoristos medias (ἐξελέξατο, ἐξελεξάμην) que transmiten una elección deliberada y personal. Lucas 6:13 registra a Jesús eligiendo a los Doce; Juan 6:70 su elección de Judas; Efesios 1:4 la elección de los creyentes por parte de Dios. Las traducciones al español escogieron/elegí confirman el sentido volitivo y deliberado en las 21 ocurrencias.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66743, 'spa', 'Usado como participio perfecto pasivo sustantivado (ὁ ἐκλελεγμένος) que funciona', 'Usado como participio perfecto pasivo sustantivado (ὁ ἐκλελεγμένος) que funciona como título mesiánico: ''el Elegido''. En Lucas 9:35, la voz divina en la Transfiguración declara ''Este es mi Hijo, el Elegido''. El español escogido y el alemán erwählt reflejan este título, mientras que ''Elegido'' en castellano capta el peso cristológico único que distingue esta ocurrencia singular del uso verbal normal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66748, 'spa', 'Fallar o cesar', 'Fallar, agotarse o llegar a su fin; dejar de funcionar o extinguirse. Abarca tanto el fallo físico como el abstracto: la luz del sol eclipsándose en la crucifixión (Lc 23:45), la riqueza que se acaba (Lc 16:9), la fe que podría fallar (Lc 22:32) y los años de Dios que jamás cesarán (Heb 1:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66749, 'spa', 'Seleccionado por Dios para un propósito especial o un destino escatológico', 'Seleccionado por Dios para un propósito especial o un destino escatológico. Aplicado a Cristo como el Elegido de Dios (Lucas 23:35), a los creyentes como los escogidos de Dios (Mateo 24:22, 31; Romanos 8:33; Colosenses 3:12; 1 Pedro 1:1), a una señora elegida (2 Juan 1, 13) y a los ángeles fieles (1 Timoteo 5:21). El concepto refleja la iniciativa soberana de Dios al escoger, con privilegio y responsabilidad implícitos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66760, 'spa', 'Eleccion divina', 'El acto soberano de Dios de escoger o seleccionar personas o un pueblo para sus propositos, particularmente para la salvacion y el servicio. Es un termino teologico distintivamente paulino: Romanos 9:11 insiste en que el proposito de Dios segun la eleccion permanece firme al margen de las obras humanas; Romanos 11:5 habla de un remanente ''escogido por gracia''; y Romanos 11:28 afirma que Israel sigue siendo electo a pesar de su incredulidad presente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66763, 'spa', 'Desfallecer o desmayar', 'Llegar a estar agotado, dbil o desanimado, ya sea fsica o espiritualmente. En los Evangelios el trmino es literal: las multitudes podran colapsar de hambre si son despedidas sin alimento (Mateo 15:32; Marcos 8:3). En las epstolas pasa al registro moral-espiritual: Glatas 6:9 exhorta a perseverar en el bien para no ''desmayar'', y Hebreos 12:3, 5 advierte contra el desaliento bajo la persecucin o la correccin divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66764, 'spa', 'Secar o enjugar', 'Secar o limpiar una sustancia líquida de una superficie, especialmente del cuerpo de una persona. Los cinco usos en el NT involucran actos profundamente personales y humildes de devoción o servicio. En Lucas 7:38, 44 y Juan 11:2; 12:3, mujeres secan los pies de Jesús con su cabello como un acto de adoración costosa. En Juan 13:5, Jesús mismo seca los pies de sus discípulos con una toalla, invirtiendo la jerarquía social.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66765, 'spa', 'Burla despreciativa', 'Describiendo la burla despreciativa o el escarnio, este sentido captura el ridículo hostil. Lucas 16:14 muestra a los fariseos amantes del dinero burlándose de la enseñanza de Jesús, mientras 23:35 retrata a los gobernantes mofándose de Cristo crucificado. El patrón consistente de traducción enfatiza la naturaleza desdeñosa y burlona de esta mofa, más allá del simple desacuerdo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66766, 'spa', 'Retirarse discretamente', 'Juan 5:13 señala que Jesús «se apartó (ἐξένευσεν)» tras sanar al paralítico, puesto que había una multitud en el lugar, evitando así la conmoción y la atención. El uso clásico incluía girar la cabeza hacia un lado y, metafóricamente, retirarse o evadir. La acción denota una retirada deliberada pero discreta, sin ostentación, que evita confrontaciones innecesarias.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66767, 'spa', 'Recobrar la sobriedad', '1 Corintios 15:34 contiene la orden tajante de Pablo: «Despertad (ἐκνήψατε) a la justicia y dejad de pecar.» El uso clásico significaba dormir la borrachera y recobrar la sobriedad, o metafóricamente recuperarse de una perturbación emocional. Pablo emplea el término para exigir un despertar espiritual urgente, pasando del letargo moral a una conciencia clara y recta ante Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66768, 'spa', 'Voluntario, espontáneo', 'Se aplica a acciones o decisiones tomadas por libre voluntad, sin coacción externa. El uso de Pablo en Filemón 1:14 subraya que la generosidad cristiana debe ser voluntaria, no forzada, un principio extensible a todas las relaciones dentro del cuerpo de Cristo. El término distingue la disposición genuina del cumplimiento obligado, otorgándole un peso tanto ético como jurídico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66769, 'spa', 'Elección voluntaria', 'Enfatizando la elección voluntaria y la acción deliberada, este adverbio contrasta con la compulsión o la ignorancia. Hebreos 10:26 advierte contra el pecado deliberado y consciente después de la iluminación, mientras 1 Pedro 5:2 fomenta el servicio libremente elegido en lugar de la obligación reacia. Las traducciones destacan el elemento de libre voluntad y elección deliberada central al significado de la palabra.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66770, 'spa', 'Tiempo antiguo', 'Indicando tiempo antiguo o larga duración, este adverbio enfatiza que algo ha existido o sido determinado desde hace mucho. 2 Pedro 2:3 asegura que el juicio divino ha estado preparado desde hace tiempo para los maestros falsos, mientras 3:5 señala el origen antiguo de la creación por la palabra de Dios. La frase subraya la naturaleza de larga data de las acciones y propósitos divinos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66771, 'spa', 'Tentar provocativamente', 'Poner a prueba de manera presuntuosa o provocadora, especialmente tentar a Dios exigiendo pruebas de su fidelidad o poder. Las cuatro ocurrencias neotestamentarias giran en torno a este sentido. Mt 4:7 y Lc 4:12 citan Deuteronomio 6:16; 1 Co 10:9 evoca las provocaciones de Israel en el desierto; Lc 10:25 presenta un matiz más atenuado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66772, 'spa', 'Envío en misión', 'Refiriéndose al envío en una misión o viaje, este sentido enfatiza el despacho desde un lugar de origen. Hechos 13:4 describe la iniciativa del Espíritu al enviar misioneros, mientras 17:10 muestra a creyentes enviando a Pablo por seguridad. El uso consistente para el envío misionero captura la idea de ser despachado hacia afuera con propósito y autoridad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66773, 'spa', 'Extender las manos', 'Desplegar o extender, especialmente las manos, en gesto de apelación o invitación. En Romanos 10:21, citando Isaías 65:2, se describe la persistente apertura de Dios hacia el Israel rebelde: manos extendidas en acogida y dolor. Este gesto físico se convierte en poderosa metáfora de la paciencia divina y el amor no correspondido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66774, 'spa', 'Caer, desprenderse (físico)', 'Caer, desprenderse (físico). Caer o desprenderse físicamente, describiendo algo que se separa de donde estaba sujeto o creciendo. En Hechos 12:7 las cadenas caen de las manos de Pedro al mandato del ángel, una liberación repentina y milagrosa. Santiago 1:11 y 1 Pedro 1:24 citan ambos Isaías 40:7-8, comparando al rico o a toda carne con la hierba cuya flor ''se cae'' bajo el viento abrasador.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66775, 'spa', 'Encallar, desviarse del rumbo (náutico)', 'Encallar, desviarse del rumbo (náutico). Encallar o ser arrastrado fuera de curso en un contexto náutico, usado exclusivamente en el relato de Lucas sobre el naufragio de Pablo rumbo a Roma. Los marineros temen encallar en los bancos de arena de la Sirte (Hch 27:17), Pablo profetiza que deben encallar en alguna isla (27:26), y toman sondeos temiendo ser lanzados contra las rocas (27:29).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66779, 'spa', 'Apartarse, caer (espiritual/moral)', 'Apartarse, caer (espiritual/moral). Apartarse de un estado espiritual, específicamente de la gracia divina o de la firmeza en la fe. Pablo advierte a los gálatas: ''De la gracia habéis caído'' (Gá 5:4), indicando que han abandonado la esfera de la gracia al recurrir al cumplimiento de la ley para su justificación. Segunda de Pedro 3:17 exhorta a los creyentes a no ''caer de su propia firmeza'' al ser arrastrados por el error de los inicuos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66782, 'spa', 'Fallar, quedar sin efecto', 'Fallar, quedar sin efecto. Fallar o quedar sin efecto, dicho de una palabra o promesa divina que no pierde su poder. En Romanos 9:6 Pablo insiste: ''No es que la palabra de Dios haya fallado'', defendiendo la fidelidad de Dios a pesar de la incredulidad de Israel. La metáfora raíz de algo que cae o se derrumba se aplica aquí a la fiabilidad de una promesa: la palabra de Dios no cae por tierra.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66783, 'spa', 'Partida marítima', 'Hechos 15:39 relata la separación entre Pablo y Bernabé: Bernabé tomó a Marcos y zarpó hacia Chipre. Hechos 18:18 describe la partida de Pablo desde Corinto navegando hacia Siria. Hechos 20:6 narra la travesía desde Filipos hasta Troas. Cada uso marca una transición geográfica y misionera en el relato de Hechos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66784, 'spa', 'Cumplir plenamente', 'Llevar a plena realización, especialmente las promesas o propósitos divinos. En Hechos 13:33, Pablo declara que Dios ha cumplido su promesa a los padres al resucitar a Jesús, un acto completo y definitivo. El tiempo perfecto subraya el efecto duradero: lo que Dios prometió permanece consumado, transformando la esperanza mesiánica de Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66785, 'spa', 'Cumplimiento ritual', 'La consumación o cumplimiento de un período o proceso, especialmente de observancia ritual. En Hechos 21:26, Pablo entra al templo para anunciar la consumación de los días de purificación, señalando cuándo se haría la ofrenda. El término abarca tanto la conclusión temporal (los días han terminado) como el cumplimiento ritual (los requisitos están satisfechos).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66786, 'spa', 'Asombrarse, quedar atónito — ser golpeado por un asombro o estupefacción abrumad', 'Asombrarse, quedar atónito — ser golpeado por un asombro o estupefacción abrumadora, siempre en voz pasiva/media en el NT, describiendo el profundo impacto emocional de las palabras y obras de Jesús sobre quienes las presenciaron. Ocurre en respuesta a su enseñanza en el Sermón del Monte (Mt 7:28), en la sinagoga de Nazaret (Mt 13:54, Mr 6:2), en el Templo (Mt 22:33, Mr 11:18), así como ante sus obras milagrosas (Mr 7:37, Lc 9:43).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66794, 'spa', 'Expirar al morir', 'Las tres apariciones evangélicas describen la muerte de Jesús en la cruz, específicamente el momento en que su respiración cesó. La precisión médica del griego distingue este término de expresiones más metafóricas sobre la muerte: se trata de la expiración biológica, el cese literal del aliento. Las traducciones multilingües confirman esta especificidad: «expiró» en español, «expirer» en francés e «breathed his last» en inglés preservan la imagen respiratoria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66795, 'spa', 'salir, partir físicamente', 'salir, partir físicamente');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66799, 'spa', 'proceder, emanar de una fuente', 'proceder, emanar de una fuente');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66813, 'spa', 'Inmoralidad sexual extrema', 'Entregarse a una inmoralidad sexual extrema o flagrante, con el sentido de traspasar los límites normales. En Judas 7, el verbo describe la entrega de Sodoma y Gomorra al pecado sexual, lo cual atrajo el juicio divino. La forma compuesta intensifica el grado de depravación, señalando su conducta como ejemplo paradigmático de rebelión moral merecedora de castigo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66814, 'spa', 'Escupir con desprecio', 'Escupir por asco o desprecio, expresando un rechazo visceral. En Gálatas 4:14, Pablo reconoce que su condición física podría haber provocado tal repulsión, pero los gálatas lo recibieron con calidez. El verbo dramatiza el contraste entre la aversión natural ante la aflicción y el amor de los creyentes gálatas, quienes vieron más allá de la fragilidad de Pablo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66815, 'spa', 'Desarraigar', 'Arrancar de raíz, erradicar o destruir por completo. La metáfora agrícola porta un peso teológico en las cuatro ocurrencias. En Mt 13:29 la preocupación es el daño colateral del desarraigo prematuro; Mt 15:13 anuncia juicio divino; Lc 17:6 ilustra el poder de la fe; y Jd 1:12 aplica la imagen a falsos maestros espiritualmente muertos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66816, 'spa', 'Asombro, estupefacción', 'Asombro, estupefacción, admiración abrumadora: estado de quedar atónito o fuera de sí en respuesta a un acontecimiento extraordinario, especialmente un milagro. Cuatro de las siete apariciones en el NT llevan este sentido: la familia asombrada ''con gran estupor'' cuando la niña resucita (Marcos 5:42), las mujeres huyendo del sepulcro poseídas de ''temblor y espanto'' (Marcos 16:8), y la multitud sobrecogida tras la sanación junto a la Puerta Hermosa (Hechos 3:10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66817, 'spa', 'Trance, éxtasis visionario', 'Trance o estado extático inducido divinamente en el que una persona recibe visiones y revelaciones, distinto del asombro del sentido 1 en que implica un estado alterado de conciencia y no una reacción ante eventos externos. Las tres apariciones se concentran en Hechos: Pedro en la azotea de Jope ''cayó en un trance'' y vio el lienzo con animales inmundos (Hechos 10:10; 11:5), y Pablo relata un trance durante su oración en el templo (Hechos 22:17).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66821, 'spa', 'Perversión moral', 'Estar pervertido o torcido fuera de la forma moral o espiritual correcta. En Titus 3:11, el perfecto pasivo describe a una persona facciosa como completamente corrompida, más allá de toda corrección. El tiempo perfecto implica una condición asentada: se han deformado y permanecen así, pecando activamente y autocondenados.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66822, 'spa', 'Perturbación social', 'Perturbar o agitar, causando conmoción social o turbación emocional. En Acts 16:20, los opositores acusan a Pablo y Silas de sumir su ciudad en la confusión, trastornando el orden establecido con su enseñanza. El cargo es tanto social (son alborotadores) como implícitamente religioso (desafían las costumbres locales). El verbo capta la ansiedad de las autoridades ante un cambio no deseado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66823, 'spa', 'Extender la mano, ya sea para sanar, ordenar, agarrar o gesticular', 'Extender la mano, ya sea para sanar, ordenar, agarrar o gesticular. Este es el uso casi universal en el Nuevo Testamento: Jesus extiende su mano para limpiar al leproso (Mt 8:3; Mc 1:41), para restaurar la mano seca (Mt 12:13; Mc 3:5; Lc 6:10) y para senalar a sus discipulos (Mt 12:49). Pedro extiende sus manos en la profecia de su martirio (Jn 21:18).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66829, 'spa', 'Echar o bajar equipo desde un barco, un uso nautico especializado', 'Echar o bajar equipo desde un barco, un uso nautico especializado. En Hch 27:30, los marineros fingen estar echando anclas desde la proa mientras en realidad intentan escapar en el bote del barco. El mismo movimiento basico de extender se aplica al manejo de aparejos y anclas en contexto maritimo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66830, 'spa', 'completar un proyecto', 'Refiriéndose a completar o terminar un proyecto, este sentido aparece en la parábola de Jesús sobre calcular el costo del discipulado. Tanto Lucas 14:29 como 30 lo usan para terminar un proyecto de construcción, enfatizando la vergüenza de empezar sin recursos para completar. La palabra subraya la culminación exitosa más que simplemente cesar el trabajo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66831, 'spa', 'Devoción ferviente', 'Devoción sincera o celo ferviente, marcado por la intensidad y la perseverancia. En Acts 26:7, Pablo describe la adoración de Israel como caracterizada por este fervor: sirven a Dios constantemente, noche y día, en esperanza anhelante de la promesa. El sustantivo capta no solo la actividad sino el espíritu apasionado que la impulsa, esa entrega incondicional que persevera sin desmayar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66832, 'spa', 'Intensidad creciente', 'Con mayor fervor o intensidad, describiendo un aumento en el ardor o el esfuerzo. En Luke 22:44, a medida que la agonía de Jesús se intensifica en Getsemaní, su oración se vuelve más ferviente: el adverbio comparativo marca la crisis que se profundiza. Su intercesión crece en urgencia mientras enfrenta la copa que debe beber.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66833, 'spa', 'Fervor constante', 'Ferviente, caracterizado por una intensidad sostenida y un compromiso sincero. En 1 Peter 4:8, Pedro llama a los creyentes a un amor ferviente entre ellos, un amor constante, incondicional y perseverante. El adjetivo sugiere un amor que se extiende y no se retira fácilmente, cubriendo multitud de pecados mediante la paciencia genuina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66834, 'spa', 'acción ferviente e intensa', 'Describiendo acción intensa y ferviente, este adverbio enfatiza la sinceridad celosa en la oración y el amor. Hechos 12:5 retrata la oración urgente y constante de la iglesia por la liberación de Pedro, mientras que 1 Pedro 1:22 llama a un amor extendido y profundamente sincero entre creyentes. El español ''fervientemente'' captura particularmente la cualidad ardiente y apasionada de tal sinceridad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66835, 'spa', 'Exponer o abandonar', 'Exponer a un recién nacido colocándolo a la intemperie, abandonándolo a los elementos. Este sentido técnico aparece en Hch 7:21, donde se describe a Moisés como ''habiendo sido expuesto'' (ἐκτεθέντος). El participio pasivo subraya la vulnerabilidad del infante y el rescate providencial que le sigue. En un segundo uso, significa presentar, explicar o desarrollar un argumento de forma ordenada y detallada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66836, 'spa', 'Sacudir en protesta', 'Sacudir o sacudirse como acto simbólico de protesta, renuncia o transferencia de responsabilidad. Las cuatro apariciones neotestamentarias funcionan como gestos proféticos, no como mera higiene. Mt 10:14 y Mc 6:11 describen el polvo sacudido de los pies como testimonio contra pueblos que rechazan el mensaje; Hch 13:51 repite el gesto contra perseguidores; Hch 18:6 lo extiende a las vestiduras.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66837, 'spa', 'Excepto, a menos que', 'Sentido de exclusión o excepción: «excepto», «a menos que», «aparte de», «más allá de», introduciendo una excepción lógica a una afirmación previa. Pablo lo utiliza para matizar declaraciones universales — «todo le fue sometido, excepto aquel que le sujetó todas las cosas» (1 Co 15:27) — y para establecer condiciones — «a menos que retengáis» (1 Co 15:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66838, 'spa', 'Fuera, externo a', 'Sentido espacial o locativo: físicamente «fuera», «externo a» o «más allá de» un límite o dominio. En Mateo 23:26 Jesús contrasta limpiar «lo de fuera» del vaso con lo de dentro (ἐντός), y en 1 Corintios 6:18 Pablo describe un pecado «fuera del cuerpo» en contraste con la inmoralidad sexual dentro de él. El español emplea «fuera de» como marcador espacial dedicado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66841, 'spa', 'sexto (número ordinal) — Adjetivo ordinal que indica la sexta posición en una se', 'sexto (número ordinal) — Adjetivo ordinal que indica la sexta posición en una serie contada. En los Evangelios identifica la hora sexta del día — aproximadamente el mediodía — en momentos de gran peso teológico, incluyendo la oscuridad durante la crucifixión (Mt 27:45, Mc 15:33, Lc 23:44) y el encuentro de Jesús junto al pozo de Jacob (Jn 4:6). Lucas lo usa para el sexto mes del embarazo de Elisabet (Lc 1:26, 36). En Apocalipsis marca etapas sucesivas del juicio divino: el sexto sello, la sexta trompeta y la sexta copa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66843, 'spa', 'Desviarse del camino', 'Apartarse o desviarse del camino correcto, ya sea literalmente (un miembro dislocado en Heb 12:13) o figuradamente (alejarse de la sana doctrina en 1 Ti 1:6; 5:15; 6:20; 2 Ti 4:4). Las Epístolas Pastorales lo emplean como advertencia solemne sobre la deriva teológica: personas que se apartan de la fe hacia mitos y palabrerías vacías. En Hebreos 12:13 aparece el sentido médico: sendas rectas evitan que una articulación débil se tuerza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66844, 'spa', 'cuidado nutritivo', 'Refiriéndose al cuidado nutritivo y la alimentación, este sentido se aplica tanto al cuidado conyugal (Ef 5:29) como a la crianza de los hijos (6:4). El verbo enfatiza el proceso continuo de alimentar y fomentar el crecimiento, no meramente proveer una sola comida. El uso de Pablo en 5:29 conecta el autocuidado natural con el cuidado que los esposos deben mostrar a sus esposas, mientras 6:4 se enfoca en la nutrición integral de los hijos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66845, 'spa', 'Nacimiento prematuro o anormal', 'Un nacimiento fuera de tiempo o anormal, frecuentemente un aborto o parto prematuro. En 1 Corintios 15:8, Pablo se aplica este termino metaforicamente, reconociendo que su comision apostolica llego de forma inesperada y fuera de la secuencia habitual. No fue discipulo durante el ministerio de Jesus, sino que encontro al Senor resucitado despues, de una manera que el mismo considero anomala, de ahi esta vivida y algo impactante autodescripcion.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66846, 'spa', 'Sacar, llevar fuera', 'Sacar o llevar físicamente a alguien o algo fuera de un lugar, especialmente cargar un cadáver para su sepultura. La connotación funeraria, bien atestiguada en el griego clásico desde Homero, domina en Hechos 5:6, 5:9 y 5:10, donde los jóvenes sacan los cuerpos de Ananías y Safira. En Marcos 8:23 Jesús lleva al ciego fuera de la aldea, y en Lucas 15:22 el padre ordena a los siervos sacar el mejor vestido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66851, 'spa', 'Producir, dar fruto', 'Producir, dar o generar — dicho de la tierra o las plantas que generan vegetación. En Hebreos 6:8, la tierra que «produce» (ἐκφέρουσα) espinos y abrojos se contrasta con la que da frutos útiles. La metáfora extiende ἐκφέρω del sentido literal de sacar al de productividad agrícola, pasando de verbos de movimiento a vocabulario de producción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66853, 'spa', 'Escapar del juicio', 'Escapar o evitar el juicio divino, el castigo o un peligro inminente en sentido teológico o moral. La amenaza es abstracta — la ira de Dios, la tribulación venidera o las consecuencias de descuidar la salvación — no un captor físico. Pablo pregunta: «¿Piensas que escaparás del juicio de Dios?» (Ro 2:3), y Jesús insta a orar «para que tengáis fuerza para escapar» de la angustia de los últimos tiempos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66858, 'spa', 'Huir físicamente', 'Huir o escapar de un lugar, captor o agresor físico — una fuga corporal más que la evasión de consecuencias abstractas. La dramática huida nocturna de Pablo desde Damasco en un canasto por una ventana (2 Co 11:33), el carcelero que temía que los presos «hubieran huido» (Hch 16:27) y la fuga desnuda de los exorcistas golpeados por el endemoniado (Hch 19:16) ilustran una escapada concreta y visible.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66861, 'spa', 'Aterrorizar o espantar', 'Asustar o aterrorizar, provocando temor o alarma en alguien. En 2 Corintios 10:9, Pablo niega que su intencion sea aterrorizar a los corintios con sus cartas, a pesar del tono severo de estas. Su proposito es corregir, no intimidar. El verbo capta el posible impacto emocional de sus palabras firmes: podrian asustar, pero el insiste en que su intencion es pastoral, no coercitiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66862, 'spa', 'temor ante lo divino', 'Describiendo temor intenso ante la manifestación divina, este sentido aparece en contextos de teofanía. Marcos 9:6 explica que el discurso confuso de Pedro en la Transfiguración resultó del terror, mientras Hebreos 12:21 recuerda el temor extremo de Moisés ante la revelación del Sinaí. Ambas instancias muestran el temor humano ante la gloria divina, enfatizando asombro y espanto abrumadores.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66863, 'spa', 'brotar nuevo crecimiento', 'Refiriéndose a las plantas echando nuevo crecimiento, este sentido aparece en la parábola de Jesús sobre leer las señales de los tiempos. Tanto Mateo 24:32 como Marcos 13:28 describen a la higuera brotando ramas tiernas y hojas, señalando la llegada del verano. El ciclo natural se convierte en una ilustración de reconocer momentos significativos a través de señales observables de surgimiento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66864, 'spa', 'El sentido más amplio y frecuente', 'El sentido más amplio y frecuente: derramar una sustancia líquida, o metafóricamente derramar el Espíritu Santo, la ira o la bendición divina. Jesús habla del vino nuevo que se derrama cuando los odres revientan (Mateo 9:17; Lucas 5:37), y la sangre del pacto es ''derramada por muchos para el perdón de los pecados'' (Mateo 26:28). En Pentecostés, Pedro cita a Joel: Dios ''derramará mi Espíritu sobre toda carne'' (Hechos 2:17).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66871, 'spa', 'Derramar sangre — una aplicación especializada del verbo que pone en primer plan', 'Derramar sangre — una aplicación especializada del verbo que pone en primer plano la muerte violenta o el martirio. Lucas 11:50 advierte que ''la sangre de todos los profetas derramada desde la fundación del mundo'' será demandada, Hechos 22:20 recuerda la sangre de Esteban siendo derramada, y Apocalipsis 16:6 justifica el juicio de Dios porque los opresores ''derramaron la sangre de los santos''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66875, 'spa', 'Una rara extensión figurada', 'Una rara extensión figurada: abandonarse temerariamente, lanzarse de cabeza. Aparece únicamente en Judas 1:11, donde los falsos maestros ''se derramaron'' en el error de Balaam por lucro. El francés se précipitèrent (''se lanzaron de cabeza'') y el alemán ergossen sie sich (''se derramaron'') captan el matiz reflexivo de autoabandono que distingue este uso del derramamiento transitivo de líquido o sangre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66878, 'spa', 'Partir o retirarse', 'Partir o retirarse de un lugar, frecuentemente con el sentido de evacuar o huir. En Lucas 21:21, Jesus ordena a los que estan en la ciudad que salgan cuando vean las senales del juicio inminente sobre Jerusalen. El imperativo transmite urgencia: no quedarse, sino irse. El verbo encaja en el contexto de advertencia escatologica, donde atender el llamado a marcharse podia significar la diferencia entre la vida y la muerte.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66879, 'spa', 'Muerte súbita divina', 'Hechos 5:5 relata la muerte de Ananías: «Al oír estas palabras, cayó y expiró». En 5:10, Safira sufre idéntica suerte: «al instante cayó a sus pies y expiró». Hechos 12:23 narra el espantoso fin de Herodes: «al instante un ángel del Señor lo hirió, porque no dio la gloria a Dios, y fue comido de gusanos y expiró». En los tres casos el término señala una muerte repentina como acto de juicio divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66880, 'spa', 'Acción voluntaria', 'Enfatizando la acción voluntaria frente a la compulsión, este adverbio resalta el elemento de libre elección. Romanos 8:20 contrasta la sujeción involuntaria de la creación con el propósito soberano de Dios, mientras que 1 Corintios 9:17 distingue la mayordomía voluntaria de Pablo del servicio forzado. La evidencia multilingüe (''voluntariamente'', ''freiwillig'', ''volontairement'') enfatiza consistentemente la dimensión del libre albedrío.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66881, 'spa', 'olivo (topónimo', 'olivo (topónimo: Monte de los Olivos) — El olivo como topónimo: el nombre geográfico fijo ''Monte de los Olivos'' (τὸ Ὄρος τῶν Ἐλαιῶν), siempre en genitivo plural. Once apariciones anclan este lugar en la narrativa de la Pasión y el discurso escatológico de Jesús: se sienta en el Monte de los Olivos frente al Templo (Mt 24:3; Mc 13:3), se retira allí tras la Última Cena (Mt 26:30; Mc 14:26; Lc 22:39) y asciende desde su cumbre (Hch 1:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66882, 'spa', 'olivo (la planta en sí) — El olivo como planta viva, usado literalmente o como m', 'olivo (la planta en sí) — El olivo como planta viva, usado literalmente o como metáfora sostenida. En Romanos 11:17, 24, Pablo desarrolla la alegoría botánica más elaborada del NT: el olivo cultivado (καλλιέλαιος) representa a Israel, y las ramas de olivo silvestre (ἀγριέλαιος) representan a los creyentes gentiles injertados para participar de ''la rica raíz del olivo''. La metáfora insiste en la continuidad orgánica entre Israel y la Iglesia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66883, 'spa', 'aceituna (el fruto) — La aceituna como fruto comestible cosechado del árbol', 'aceituna (el fruto) — La aceituna como fruto comestible cosechado del árbol. Una única aparición neotestamentaria en Santiago 3:12 aísla este sentido: ''¿Acaso puede la higuera, hermanos míos, producir aceitunas (ἐλαίας)? ¿O la vid producir higos?'' La pregunta retórica apela al principio de los géneros naturales — cada planta da fruto según su naturaleza — para argumentar que la lengua no puede producir a la vez bendición y maldición.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66885, 'spa', 'Aceite de oliva', 'Aceite de oliva. Aceite de oliva como sustancia física usada para lámparas, unción, sanación y comercio. Combustible para lámparas en la parábola de las diez vírgenes (Mt 25:3-4, 8). Unción de la cabeza como gesto de hospitalidad (Lc 7:46). Unción sanadora de los enfermos (Mr 6:13; Stg 5:14). Primeros auxilios vertidos sobre heridas (Lc 10:34). Producto comercial protegido de la escasez (Ap 6:6) y enumerado entre las importaciones de Babilonia (Ap 18:13). Figuradamente, ''óleo de alegría'' (Heb 1:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66888, 'spa', 'Monte de los Olivos', 'El Monte de los Olivos (Olivete), la prominente cadena de colinas al este de Jerusalen cubierta de olivares. En Hechos 1:12, es el lugar de la ascension de Jesus. El monte tuvo un papel destacado en la ultima semana de Jesus: lloro sobre Jerusalen desde su ladera, enseno a sus discipulos alli y oro en Getsemani a sus pies. El nombre evoca tanto la geografia sagrada como el paisaje agricola de la antigua Judea.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66889, 'spa', 'Habitantes de Elam', 'Habitantes de Elam, antigua region al este de Mesopotamia. En Hechos 2:9, los elamitas estan entre la multitud diversa en Pentecostes, representando la lejana diaspora judia. Su inclusion en la lista de Lucas destaca como judios de la frontera oriental del mundo conocido presenciaron el derramamiento del Espiritu. El milagro multilingue permitio que incluso estos peregrinos distantes escucharan el evangelio en su lengua materna.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66890, 'spa', 'Menor o inferior', 'Más pequeño, menor o inferior en grado, rango, edad o calidad. Este adjetivo comparativo se adapta a diversos contextos: Jn 2:10 contrasta la calidad del vino (inferior frente a bueno); Ro 9:12 distingue al hijo menor en la narrativa de Jacob y Esaú; 1 Ti 5:9 establece un umbral mínimo de edad (no menos de sesenta años); He 7:7 formula un principio jerárquico donde el menor recibe bendición del mayor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66891, 'spa', 'Tener menos o carecer', 'Tener menos o carecer, estar deficiente en cantidad. En 2 Corintios 8:15, citando la historia del maná, Pablo señala que quienes recogieron poco "no tuvieron de menos": no fueron perjudicados. El verbo resalta la provisión divina que aseguró suficiencia para todos. Pablo aplica esto a la generosidad cristiana: cuando los creyentes comparten, la desigualdad se nivela y nadie padece necesidad mientras otros tienen excedente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66892, 'spa', 'Disminuir o rebajar', 'Juan 3:30 contiene la célebre declaración del Bautista: «Es necesario que él crezca, pero que yo mengüe», el precursor cediendo voluntariamente su prominencia al Cristo. Hebreos 2:7 y 2:9 citan el Salmo 8 aplicándolo a Jesús: «Lo hiciste un poco menor que los ángeles». El término abarca tanto la mengua autoimpuesta como la reducción decretada por Dios en el misterio de la encarnación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66893, 'spa', 'Impulsar o remar', 'Impulsar hacia adelante, propulsar o remar, ya sea por esfuerzo humano, viento o fuerza espiritual. En Marcos 6:48 y Juan 6:19, los discípulos reman con dificultad a través del mar. Lucas 8:29 describe a un endemoniado impulsado por un espíritu inmundo al desierto. Santiago 3:4 ilustra naves empujadas por vientos fieros pero guiadas por un pequeño timón. 2 Pedro 2:17 compara a los falsos maestros con neblinas arrastradas por la tempestad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66894, 'spa', 'Ligereza o inconstancia', 'Levedad o inconstancia, indicando falta de seriedad o fiabilidad en las decisiones. En 2 Corintios 1:17, Pablo niega haber actuado con ligereza al cambiar sus planes de viaje. No fue caprichoso ni insincero, haciendo promesas a la ligera sin intención de cumplirlas. El sustantivo capta la acusación que enfrentaba: que era poco fiable, propenso a decir una cosa y hacer otra, cargo que rechaza firmemente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66895, 'spa', 'Fácil de llevar', 'Describiendo lo que es fácil de llevar en lugar de gravoso, este sentido contrasta con cargas pesadas. Mateo 11:30 ofrece la carga ligera de Jesús frente a las pesadas demandas del legalismo religioso, mientras que 2 Corintios 4:17 relativiza el sufrimiento presente como momentáneo y leve comparado con el peso eterno de gloria. La palabra enfatiza el carácter soportable y manejable en lugar del peso opresivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66896, 'spa', 'mínimo, el más pequeño — Adjetivo superlativo que significa ''mínimo, el más pequ', 'mínimo, el más pequeño — Adjetivo superlativo que significa ''mínimo, el más pequeño, el más insignificante'', aplicado al rango, la importancia, el tamaño o la cantidad. En la enseñanza de Jesús a menudo lleva un matiz paradójico: el llamado ''el más pequeño en el reino'' (Mt 5:19), la fidelidad ''en lo muy poco'' que capacita para una confianza mayor (Lc 16:10, 19:17), y ''uno de estos mis hermanos más pequeños'' como el lugar sorprendente del encuentro con Cristo (Mt 25:40, 45).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66903, 'spa', 'El menor o más pequeño', 'El menor, el más pequeño o insignificante, a menudo referido al estatus o la dignidad. En Efesios 3:8, Pablo se describe como menos que el más pequeño de todos los santos, un doble comparativo que enfatiza su profundo sentido de indignidad. A pesar de ser el menos cualificado, le fue confiado el misterio de Cristo para los gentiles. El término expresa humildad pero también magnifica la gracia de Dios al usar al insignificante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66904, 'spa', 'Ancestro post-exílico', 'Refiriéndose a un ancestro post-exílico en la genealogía de Jesús, este nombre propio aparece dos veces en Mateo 1:15 mientras la genealogía traza la línea desde el exilio babilónico hasta José. La repetición refleja el patrón formulaico de Mateo ''A engendró a B''. Las transliteraciones varían entre idiomas (Eleasar en alemán, Éléazar en francés) al representar el original hebreo a través del griego.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66905, 'spa', 'Reprensión o reproche', 'Reprensión o reproche, el acto de exponer y corregir una falta. En 2 Pedro 2:16, Balaam recibió reprensión por su transgresión cuando su asna habló milagrosamente, refrenando su insensatez. El sustantivo enfatiza la función correctiva: la reprensión tenía como propósito detenerlo en su camino de pecado. El incidente se convierte en paradigma de cómo Dios interviene para convencer y refrenar a quienes persisten en la maldad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66906, 'spa', 'Prueba o evidencia', 'Refiriéndose a la prueba o evidencia que establece la realidad, este sentido aparece en dos contextos distintos. 2 Timoteo 3:16 incluye la reprensión entre las funciones de la Escritura para corregir el error, mientras que Hebreos 11:1 la usa respecto a la convicción de fe de que las realidades invisibles existen. El alemán ''Beweis'' (prueba) capta la dimensión evidencial: la reprensión prueba el error, la fe prueba las verdades invisibles.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66907, 'spa', 'Corregir o amonestar verbalmente a alguien con el objetivo de producir arrepenti', 'Corregir o amonestar verbalmente a alguien con el objetivo de producir arrepentimiento. Jesus ordena esta reprension directa en Mt 18:15, y Pablo exhorta a Timoteo a ''reprender, exhortar'' (2 Ti 4:2). El proposito siempre es restaurador, no punitivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66908, 'spa', 'Hacer manifiesto lo que ha estado oculto, sacando a la luz obras escondidas', 'Hacer manifiesto lo que ha estado oculto, sacando a la luz obras escondidas. Jn 3:20 explica que los malhechores evitan la luz para que sus obras no sean expuestas, mientras que Ef 5:13 declara que todo lo expuesto por la luz se hace visible. Este sentido extiende el significado desde la reprension personal hasta la revelacion cosmica: las tinieblas mismas son desenmascaradas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66913, 'spa', 'Llevar a alguien a una conciencia interior de culpa o maldad, a menudo con matic', 'Llevar a alguien a una conciencia interior de culpa o maldad, a menudo con matices judiciales. En Jn 16:8 el Espiritu Santo convence al mundo de pecado, justicia y juicio. Pablo imagina al incredulo entrando al culto y siendo convencido por la palabra profetica (1 Co 14:24). Captura el sentido forense de probar culpabilidad ante la conciencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66922, 'spa', 'Estado lamentable', 'Describiendo un estado lamentable o desdichado que merece compasión, este sentido enfatiza la miseria. 1 Corintios 15:19 argumenta que los cristianos serían los más dignos de lástima si la esperanza de resurrección resultara falsa, mientras que Apocalipsis 3:17 expone la miseria autoengañada de Laodicea a pesar de creerse ricos. Ambos contextos subrayan la condición patética de quienes carecen de esperanza verdadera o percepción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66923, 'spa', 'mostrar misericordia o compasión', 'mostrar misericordia o compasión');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66924, 'spa', 'recibir misericordia', 'recibir misericordia');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66941, 'spa', 'limosna, caridad — Dádiva caritativa a los pobres, la limosna como expresión tan', 'limosna, caridad — Dádiva caritativa a los pobres, la limosna como expresión tangible de misericordia. Jesús instruye la generosidad secreta en lugar de la exhibición pública (Mt 6:2-4). Lucas conecta la limosna con la pureza interior y el tesoro escatológico (Lc 11:41, 12:33). En Hechos, Tabita es recordada por sus obras de caridad (Hch 9:36), y la limosna de Cornelio es reconocida con aprobación por Dios (Hch 10:2, 4, 31). La raíz etimológica en ἔλεος (''misericordia'') subraya que dar no es mera obligación sino un acto de compasión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66942, 'spa', 'Misericordioso', 'Caracterizando a quienes muestran misericordia y compasión, este sentido se aplica tanto a los discípulos bienaventurados (Mat 5:7) como a Cristo el sumo sacerdote (Heb 2:17). La bienaventuranza promete misericordia a los misericordiosos, mientras que Hebreos enfatiza la fidelidad compasiva de Cristo al representar a la humanidad. Las traducciones consistentes reflejan el significado central de mostrar compasión activa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66943, 'spa', 'Compasión divina activa y fidelidad al pacto, enraizada en la traducción de la L', 'Compasión divina activa y fidelidad al pacto, enraizada en la traducción de la LXX del hebreo חֶסֶד. Impregna los himnos de la infancia de Lucas como la misericordia de Dios que abarca generaciones y cumple promesas (Lucas 1:50, 54, 58, 72, 78). Jesús la invoca para reordenar las prioridades religiosas: ''Misericordia quiero y no sacrificio'' (Mateo 9:13; 12:7, citando Oseas 6:6). Pablo fundamenta la inclusión de los gentiles en la misericordia de Dios (Romanos 9:23; 11:31; 15:9), y Santiago proclama que ''la misericordia triunfa sobre el juicio'' (Santiago 2:13).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66948, 'spa', 'Libertad, emancipación — el estado de ser libre, especialmente del pecado, la le', 'Libertad, emancipación — el estado de ser libre, especialmente del pecado, la ley y la corrupción cósmica. La creación gime por la libertad de los hijos de Dios (Ro 8:21). Donde está el Espíritu, allí hay libertad (2 Co 3:17). La libertad en Cristo: aquella que los espías intentaron socavar (Gá 2:4), la exhortación permanente a no volver a la esclavitud (Gá 5:1), y la advertencia contra usar la libertad como pretexto para el libertinaje (Gá 5:13; 1 P 2:16). Santiago llama a la Torá ''la ley de la libertad'' (Stg 1:25; 2:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66950, 'spa', 'Que posee la condición de persona libre, no esclavizada ni sujeta', 'Que posee la condición de persona libre, no esclavizada ni sujeta. Usado socialmente para distinguir libre de esclavo (1 Corintios 12:13; Gálatas 3:28; Apocalipsis 6:15), de exención de obligación (Mateo 17:26; Romanos 7:3), y teológicamente de la liberación por medio de Cristo del pecado (Romanos 6:20) y de la ley (Gálatas 4:26, 31). La alegoría de Sara y Agar de Pablo (Gálatas 4:22-31) ancla el concepto en la historia de la salvación. El español y el francés libre convergen en un único significado nuclear.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66957, 'spa', 'Liberar, poner en libertad', 'Poner en libertad o liberar de la esclavitud, la servidumbre, el pecado o cualquier forma de opresión, tanto en contextos literales como profundamente teológicos. Jesús promete que la verdad libera (Juan 8:32) y que la libertad que otorga el Hijo es definitiva y completa (Juan 8:36). El uso paulino en Romanos se centra en la transferencia de un amo a otro: liberados del pecado, esclavizados a la justicia (Romanos 6:18, 22). Romanos 8:2 declara la liberación de la ley del pecado y de la muerte.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66963, 'spa', 'Venida o llegada', 'Venida o llegada, especialmente de un acontecimiento significativo o esperado. En Hechos 7:52, Esteban habla de los profetas que preanunciaron la venida del Justo, el Mesías. El sustantivo destaca el anuncio profético del advenimiento de Cristo, que los líderes de Israel rechazaron matando tanto a los profetas como al propio Mesías. El término conlleva el peso de la expectativa mesiánica cumplida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66964, 'spa', 'Hecho de marfil', 'Hecho de marfil, describiendo objetos elaborados con este valioso material. En Apocalipsis 18:12, los artículos de marfil figuran entre los bienes de lujo de Babilonia, simbolizando riqueza y exceso. Los mercaderes lloran la pérdida de semejante comercio cuando llega el juicio. La mención del marfil subraya el materialismo de la ciudad y la vaciedad de las riquezas ante la ira divina: todo lo hermoso y costoso perece en una hora.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66965, 'spa', 'Antepasado de Jesús', 'Mateo 1:13 menciona a Eliakím dos veces en rápida sucesión: «Zorobabel engendró a Abiud, Abiud engendró a Eliakím, y Eliakím engendró a Azor». Lucas 3:30 lo incluye en otra rama genealógica: «hijo de Simeón, hijo de Judá, hijo de José, hijo de Jonám, hijo de Eliakím». En ambos casos el nombre marca eslabones en la cadena que une la promesa davídica con su cumplimiento en Cristo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66966, 'spa', 'Antepasado de Jesús', 'Eliézer, antepasado de Jesús mencionado en Lucas 3:29. El nombre significa «Dios es mi ayuda» en hebreo, una designación teológicamente rica y frecuente en el antiguo Israel. La inclusión de este nombre por parte de Lucas, junto con muchos otros desconocidos del Antiguo Testamento, subraya la plena humanidad de Jesús y su arraigo en la historia de Israel: incluso las generaciones oscuras entre David y el exilio importan en el plan redentor de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66967, 'spa', 'Antepasado post-exílico', 'Refiriéndose a un antepasado post-exílico en la línea davídica, este nombre aparece dos veces en Mateo 1:14-15 mientras la genealogía avanza desde el exilio babilónico hacia José. Las transliteraciones varían según el idioma al representar un nombre hebreo a través del griego. Su inclusión enfatiza la continuidad del linaje davídico a través de generaciones oscuras.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66968, 'spa', 'Nombre propio Elisabet', 'Nombre propio Elisabet (griego Ελισάβετ, del hebreo Elisheba, ''mi Dios es juramento''), que identifica a la esposa del sacerdote Zacarías y madre de Juan el Bautista. Las nueve ocurrencias aparecen en Lucas 1, donde se la presenta como hija de Aarón, irreprensible, y emparejada con María en la Visitación (Lucas 1:36-45).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66969, 'spa', 'Profeta sucesor de Elías', 'Eliseo, el profeta que sucedió a Elías y ejerció su ministerio en Israel durante el siglo IX a.C. En Lucas 4:27, Jesús cita la sanación de Naamán el sirio por parte de Eliseo para provocar a sus oyentes: la gracia de Dios desbordó las fronteras de Israel incluso en el Antiguo Testamento. La referencia anticipa el escándalo del propio ministerio de Jesús hacia marginados y gentiles, y la reacción revela cuán profundamente esto desafiaba las suposiciones judías.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66970, 'spa', 'Enrollar como pergamino', 'Describiendo la acción de enrollar como un pergamino o vestido, este sentido aparece en imágenes apocalípticas de disolución cósmica. Hebreos 1:12 lo usa en contraste con la naturaleza inmutable de Cristo—la creación se enrollará como ropa, pero él permanece. Apocalipsis 6:14 representa el cielo enrollándose como parte del juicio escatológico. Ambos enfatizan la naturaleza transitoria de la creación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66971, 'spa', 'Llaga o úlcera', 'Lucas 16:21 describe al mendigo Lázaro «cubierto de llagas, que ansiaba saciarse de lo que caía de la mesa del rico; y aun los perros venían y le lamían las llagas», pobreza extrema agravada por ulceración dolorosa y sin tratar. Apocalipsis 16:2 narra el primer juicio de las copas: «una úlcera maligna y dolorosa vino sobre los que tenían la marca de la bestia», plaga que evoca los forúnculos de Egipto.');